WITH exploded AS (SELECT id, currency, EXPLODE_OUTER(tier_prices) AS val FROM price_tiers) SELECT CASE WHEN val >= 66 THEN 'LARGE' ELSE 'SMALL' END AS val_tier, currency, COUNT(CASE WHEN currency = 'USD' THEN 1 END) AS usd_count, ROUND(AVG(val), 2) AS avg_val, ROUND(AVG(val), 2) AS avg_val_2, COUNT(DISTINCT id) AS distinct_ids, PERCENT_RANK() OVER (PARTITION BY CASE WHEN val >= 66 THEN 'LARGE' ELSE 'SMALL' END ORDER BY ROUND(AVG(val), 2) DESC) AS avg_val_2_percent_rank FROM exploded GROUP BY CASE WHEN val >= 66 THEN 'LARGE' ELSE 'SMALL' END, currency HAVING usd_count >= 1 ORDER BY avg_val_2 DESC NULLS LAST
